UPDATE analytics_backfill_state
SET cursor_event_id = #{cursor}, processed = processed + #{count}
WHERE id = #{id} AND state = 'RUNNING'

UPDATE analytics_backfill_state
SET state = 'DONE', cursor_event_id = #{cursor}, processed = processed + #{count}
WHERE id = #{id} AND state = 'RUNNING'

UPDATE analytics_backfill_state
SET state = 'FAILED', last_error = #{error}
WHERE id = #{id}
